import{_ as i,o as n,c as e,a2 as u}from"./chunks/framework.CqpfiAoK.js";const r=JSON.parse('{"title":"Nadharia na Uainishaji wa Ndege","description":"","frontmatter":{},"headers":[],"relativePath":"sw/80-位面理论与分类.md","filePath":"sw/80-位面理论与分类.md","lastUpdated":null}'),t={name:"sw/80-位面理论与分类.md"};function o(d,a,h,k,w,s){return n(),e("div",null,[...a[0]||(a[0]=[u('<h1 id="nadharia-na-uainishaji-wa-ndege" tabindex="-1">Nadharia na Uainishaji wa Ndege <a class="header-anchor" href="#nadharia-na-uainishaji-wa-ndege" aria-label="Permalink to &quot;Nadharia na Uainishaji wa Ndege&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Kipengele</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>80</td></tr><tr><td>Moduli</td><td>Mwingiliano wa Kati ya Ndege na Kanuni za Wakati</td></tr><tr><td>Maneno Muhimu ya Msingi</td><td>Nadharia ya ndege, uainishaji wa ndege, kizuizi cha sheria, koordinati za ndege, Hengyuanzhou</td></tr></tbody></table><h2 id="_1-ufafanuzi-wa-msingi-wa-ndege" tabindex="-1">1. Ufafanuzi wa Msingi wa Ndege <a class="header-anchor" href="#_1-ufafanuzi-wa-msingi-wa-ndege" aria-label="Permalink to &quot;1. Ufafanuzi wa Msingi wa Ndege&quot;">​</a></h2><p>Chini ya muundo wa Ulimwengu wa Asili wa Nanga ya Maisha Yote (Hengyuanzhou), &quot;ndege&quot; inamaanisha eneo la kuwepo linaloendelea kwa nafasi-na-wakati wa kujitegemea, lililofafanuliwa na seti ya sheria za kudumu. Ndege sio tu &quot;dunia nyingine&quot;, bali ni tathmini ya muundo wa sheria katika viwango tofauti vya vigezo. Kila ndege ina vigezo vya kimwili vya kipekee, msongamano wa nishati, kasi ya mtiririko wa wakati, na uwezo wa fahari; vigezo hivi pamoja huunda &quot;alama ya sheria&quot; ya ndege hiyo.</p><p>Ukuwepo wa ndege unatokea kutoka kwa kutokuwa sawa kwa muundo wa sheria wa Hengyuanzhou. Wakati wa utekelezaji wa sheria ya asili ya ulimwengu, kwa sababu ya tofauti katika usambazaji wa nishati, usumbufu wa fahari, na mageuzi ya kihistoria, kwa kawaida huundwa maeneo mengi ya sheria yenye vigezo tofauti. Maeneo haya yanatengwa na &quot;kizuizi cha sheria&quot;, na nguvu ya kizuizi inategemea kiwango cha tofauti ya vigezo vya sheria kati ya ndege zilizo jirani — kadiri tofauti inavyozidi, ndivyo kizuizi kinavyopana, na ugumu wa kuvuka unazidi.</p><p>Mchakato wa nanga una nafasi kuu katika nadharia ya ndege. Nanga kwa asili ni nodi thabiti katika muundo wa sheria; haiwezi tu kudumisha utulivu wa sheria ya ndege yake mwenyewe, bali pia inaweza kutumika kama kiwango cha kushikilia kwa muunganisho wa kati ya ndege. Vitendo vyote vya mwingiliano kama vile kuvuka kati ya ndege, mawasiliano, na kichunguzi, lazima vipimwe na kizingitiwa kwa nanga kama asili ya koordinati.</p><h2 id="_2-mfumo-wa-uainishaji-wa-ndege" tabindex="-1">2. Mfumo wa Uainishaji wa Ndege <a class="header-anchor" href="#_2-mfumo-wa-uainishaji-wa-ndege" aria-label="Permalink to &quot;2. Mfumo wa Uainishaji wa Ndege&quot;">​</a></h2><p>Ndege ndani ya Hengyuanzhou zimegawanywa katika makundi matano makuu yafuatayo kulingana na vigezo vya sheria, kiwango cha nishati, na kiwango cha maendeleo ya ustaarabu:</p><table tabindex="0"><thead><tr><th>Aina</th><th>Tabia za Sheria</th><th>Msongamano wa Nishati</th><th>Fomu ya Kawaida ya Ustaarabu</th><th>Ugumu wa Kuvuka</th></tr></thead><tbody><tr><td>Ndege ya Msingi ya Vifaa</td><td>Sheria za kimwili zinaongoza, nishati ni ya siri</td><td>Chini</td><td>Ustaarabu wa teknolojia, ustaarabu wa miungu ya awali</td><td>Chini</td></tr><tr><td>Ndege ya Udhihirisho wa Nishati</td><td>Sheria za nishati ni nusu-ya dhahiri, mfumo wa miungu umekomaa</td><td>Kati</td><td>Ustaarabu wa miungu ya kati-juu, ustaarabu wa uchawi</td><td>Kati</td></tr><tr><td>Ndege ya Fahari Inayoongoza</td><td>Sheria za fahari ni dhahiri, vifaa vinaweza kuundwa kwa hiari</td><td>Juu</td><td>Ustaarabu wa roho, ustaarabu wa mkusanyiko wa fahari</td><td>Juu</td></tr><tr><td>Ndege ya Sheria Iliyovunjika</td><td>Sheria haziko thabiti, kuna mapasuko mengi ya sheria</td><td>Juu sana na ya machafuko</td><td>Ndege ya pori, ndege ya mabaki</td><td>Juu sana</td></tr><tr><td>Ndege ya Karibu na Asili</td><td>Karibu na sheria ya asili ya ulimwengu, vigezo vinakaribia kikomo</td><td>Inakaribia asili</td><td>Ustaarabu wa juu zaidi, walinzi wa ndege</td><td>Kikomo cha kinadharia</td></tr></tbody></table><p>Mbali na makundi matano makuu yale, kuna aina fulani za maalum za ndege, ikiwa ni pamoja na: ndege ya kioo (uwepo wa sawa uliofanana sana na vigezo vya sheria ya ndege fulani), ndege ya kati (eneo la mpito lililoko kati ya vizuizi vya sheria vya ndege kuu mbili), ndege ya kulala (ndege ya kale yenye uwezo wa sheria wa chini sana, karibu na kusimama), na ndege mpya (ndege ya kijana yenye muundo wa sheria ulioundwa hivi karibuni, vigezo bado haviko thabiti).</p><h2 id="_3-koordinati-za-ndege-na-kanuni-za-uupimaji" tabindex="-1">3. Koordinati za Ndege na Kanuni za Uupimaji <a class="header-anchor" href="#_3-koordinati-za-ndege-na-kanuni-za-uupimaji" aria-label="Permalink to &quot;3. Koordinati za Ndege na Kanuni za Uupimaji&quot;">​</a></h2><p>Masharti ya mwingiliano wa kati ya ndege ni uupimaji sahihi wa ndege. Hengyuanzhou imeanzisha &quot;mfumo wa koordinati za ndege za nne&quot; kwa kutumia nanga kama kiwango; kila ndege imedhamiriwa kwa kiwango cha pekee kwa vigezo vinne:</p><ol><li><strong>Msimbo wa alama ya sheria</strong>: Kitambulisho cha kipekee kilichotengenezwa kupitia uendeshaji wa hash kutoka kwa vigezo vya msingi vya sheria ya ndege hiyo, urefu wa bit 128</li><li><strong>Uhusiano wa nanga</strong>: Uwezo wa muunganisho wa ndege hiyo na muundo wa nanga unaojulikana, upeo wa thamani 0 hadi 1</li><li><strong>Tilingania ya kasi ya wakati</strong>: Tilingania ya kasi ya mtiririko wa wakati wa ndege hiyo na wakati wa kiwango cha Hengyuanzhou, upeo wa kawaida 0.1 hadi 10</li><li><strong>Idadi ya vipimo vya nafasi</strong>: Idadi ya vipimo vya nafasi vinavyoweza kuchunguzwa na ndege hiyo, kwa kawaida vipimo 3 hadi 11</li></ol><p>Njia za kupata koordinati za ndege zinajumuisha: uguzaji wa kiotomatiki wa muundo wa nanga, ufuatiliaji wa ishara za mawasiliano kati ya ndege, mabaki ya koordinati katika mabaki ya kichunguzi, na uandikishaji wa mwongozo wa kuvuka ndege. Koordinati zote za ndege zilividhamiriwa zimeandikishwa katika &quot;Hifadhi Kuu ya Koordinati za Ndege za Hengyuanzhou&quot;, inayotunzwa kwa umoja na Ofisi ya Usimamizi wa Ndege chini ya Baraza la Nanga.</p><h2 id="_4-mwingiliano-wa-asili-kati-ya-ndege" tabindex="-1">4. Mwingiliano wa Asili kati ya Ndege <a class="header-anchor" href="#_4-mwingiliano-wa-asili-kati-ya-ndege" aria-label="Permalink to &quot;4. Mwingiliano wa Asili kati ya Ndege&quot;">​</a></h2><p>Hata bila vitendo vya kuvuka kwa hiari, kuna matukio ya mwingiliano wa asili kati ya ndege. Ya kawaida zaidi ni &quot;uvujaaji wa sheria&quot; — kwa sababu ya kizuizi cha kati ya ndege zilizo jirani kudhoofika kwa eneo, kiasi kidogo cha vigezo vya sheria vinapitia kila moja, na kusababisha matukio ya kawaida ya eneo. Kwa mfano, &quot;matukio ya kuzungumzia asili&quot; ambayo mara kwa mara huonekana katika ndege ya msingi ya vifaa mara nyingi husababishwa na uvujaaji wa sheria kutoka kwa ndege ya udhihirisho wa nishati iliyo jirani.</p><p>Mwingiliano mwingine wa asili ni &quot;uwiano wa ndege&quot;. Wakati msimbo wa alama ya sheria wa ndege mbili unaofanana sana, huundwa uwiano wa sheria wa mara kwa mara kati yao, unaodhihirishwa kama matukio ya kihistoria, mwelekeo wa ustaarabu, na hata hatima ya watu wanaofanana kutokea katika ndege zote mbili katika muda fulani. Uwiano wa ndege ni somo muhimu la utafiti wa kichunguzi cha ndege; kupitia uchambuzi wa kanuni za uwiano, inawezekana kukisia hali ya ustaarabu wa ndege isiyojulikana.</p><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Nadharia ya ndege ni msingi wa kinadharia wa mazoezi yote ya mwingiliano wa kati ya ndege. Kuelewa kwa usahihi asili, uainishaji, na kanuni za uupimaji wa ndege ni masharti ya kuandika kanuni za kuvuka, miongozo ya maadili, na mifumo ya kuzuia. Uchunguzi wa ndege wa Hengyuanzhou daima unafuata kanuni ya &quot;uelewa awali, mwingiliano kwa uangalifu&quot;, huku anapanua mipaka ya ustaarabu, kuhakikisha kuwa hausababishi usumbufu usioweza kurudishwa kwenye mageuzi ya kujitegemea ya ndege yoyote.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>81-Kanuni za Kuvuka Ndege</li><li>88-Miongozo ya Maadili ya Kati ya Ndege</li><li>28-Muunganisho wa Nanga wa Kati ya Ndege</li></ul>',21)])])}const m=i(t,[["render",o]]);export{r as __pageData,m as default};
